// EXP Increase (cheat). Our own patch, not from a download.
// The game works out the experience of every battle in one function (001fbdf0). Its last step limits the result to 65535;
// these five words replace that step with: result x (the number stored at 00007000), then limit to 65535.
// The launcher writes the chosen multiplier into 00007000 when the game starts (PS2_POKE); 3 is the default kept here.
patch=1,EE,001fbf68,word,8c017000 // original 3c010001  lui $1,1       -> lw $1,0x7000($0)
patch=1,EE,001fbf6c,word,00411018 // original 0041082a  slt $1,$2,$1   -> mult $2,$2,$1
patch=1,EE,001fbf70,word,00020c02 // original 14200002  bnez $1,+12    -> srl $1,$2,16
patch=1,EE,001fbf74,word,3403ffff // original 00000000  nop            -> ori $3,$0,65535
patch=1,EE,001fbf78,word,0061100b // original 3402ffff  ori $2,$0,65535 -> movn $2,$3,$1
patch=1,EE,00007000,word,00000003
